(6417389, 951599, 43774, '<td valign="top">Lovely colours, nice detail, pretty.</td>', 'Lovely colours, nice detail, pretty.', '2011-05-18 16:41:13.000000', NULL, 1),
(6417394, 951598, 43774, '<td valign="top">Nice bokeh and deep colours.</td>', 'Nice bokeh and deep colours.', '2011-05-18 16:41:55.000000', NULL, 1),
(6417395, 951162, 43774, '<td valign="top">Nice light.</td>', 'Nice light.', '2011-05-18 16:41:58.000000', NULL, 1),
