(6417780, 951886, 124815, '<td valign="top">Beautiful movement, on top of everything else. As an aside, it responds the best to the challenge: flowers in garden &amp; field. I can almost hear the soft cries of cicadas. First page stuff.</td>', 'Beautiful movement, on top of everything else. As an aside, it responds the best to the challenge: flowers in garden & field. I can almost hear the soft cries of cicadas. First page stuff.', '2011-05-18 22:00:55.000000', NULL, 1),
(6417781, 952174, 124815, '<td valign="top">The courage of meeting their fate with elegance but fighting to the last petal!  9</td>', 'The courage of meeting their fate with elegance but fighting to the last petal!  9', '2011-05-18 22:01:03.000000', NULL, 1),
(6417782, 952094, 132996, '<td valign="top">Your use of the shadow is perfect! :)</td>', 'Your use of the shadow is perfect! :)', '2011-05-18 22:02:27.000000', NULL, 1),
