(6418680, 952089, 93756, '<td valign="top">Great, bright color and perfect placement in the frame. Really, nothing I could suggest to make this better. Really nice!</td>', 'Great, bright color and perfect placement in the frame. Really, nothing I could suggest to make this better. Really nice!', '2011-05-19 19:37:54.000000', NULL, 1),
(6418681, 951906, 58634, '<td valign="top">The lighting is superb considering the challenge guidelines. Very beatiful.</td>', 'The lighting is superb considering the challenge guidelines. Very beatiful.', '2011-05-19 19:38:54.000000', NULL, 1),
(6418683, 951182, 93756, '<td valign="top">Love the old fashioned look of this. Could be a greeting card or hung on the wall. Very cool.</td>', 'Love the old fashioned look of this. Could be a greeting card or hung on the wall. Very cool.', '2011-05-19 19:39:24.000000', NULL, 1),
(6418684, 951296, 58634, '<td valign="top">Love this flower, and the pastel colored bokeh.  So simple yet beautiful. 8 from me!</td>', 'Love this flower, and the pastel colored bokeh.  So simple yet beautiful. 8 from me!', '2011-05-19 19:39:25.000000', NULL, 1),
(6418685, 952088, 58634, '<td valign="top">I''ve never seen this flower, and I think it''s very pretty. However, I feel like this image is too up front for me. I think attempting different angles, or a more unique composition, would''ve worked better.</td>', 'I''ve never seen this flower, and I think it''s very pretty. However, I feel like this image is too up front for me. I think attempting different angles, or a more unique composition, would''ve worked better.', '2011-05-19 19:40:58.000000', NULL, 1),
