(6418689, 952013, 58634, '<td valign="top">Very vibrant and colorful! I also think the frame adds a lot!</td>', 'Very vibrant and colorful! I also think the frame adds a lot!', '2011-05-19 19:45:03.000000', NULL, 1),
(6418690, 951977, 58634, '<td valign="top">Too much of a macro, if that''s even possible, lol. However, I really enjoy the bokeh (I think that''s what it is) to the left of the image.</td>', 'Too much of a macro, if that''s even possible, lol. However, I really enjoy the bokeh (I think that''s what it is) to the left of the image.', '2011-05-19 19:45:54.000000', NULL, 1),
(6418691, 952130, 58634, '<td valign="top">This flower has a very deep beatiful color, but I think it makes the background too washed out. I also think a darker colored frame would''ve created more of an impacting image.</td>', 'This flower has a very deep beatiful color, but I think it makes the background too washed out. I also think a darker colored frame would''ve created more of an impacting image.', '2011-05-19 19:47:03.000000', NULL, 1),
(6418694, 952009, 58634, '<td valign="top">This almost looks like a water color painting.  I like it :)</td>', 'This almost looks like a water color painting.  I like it :)', '2011-05-19 19:47:25.000000', NULL, 1),
(6418695, 952041, 58634, '<td valign="top">It almost looks like the flowers are embracing. Very nice composition.</td>', 'It almost looks like the flowers are embracing. Very nice composition.', '2011-05-19 19:47:53.000000', NULL, 1),
(6418696, 951081, 58634, '<td valign="top">the lighting in this image is very beatiful. I think it brings out the best features in the flower, as well, as a lovely hue to the background that makes the flowers stand out more.</td>', 'the lighting in this image is very beatiful. I think it brings out the best features in the flower, as well, as a lovely hue to the background that makes the flowers stand out more.', '2011-05-19 19:48:42.000000', NULL, 1),
