(6419634, 952156, 117717, '<td valign="top">I''m envious of your yard!  Like your pov &amp; lighting</td>', 'I''m envious of your yard!  Like your pov & lighting', '2011-05-20 15:41:46.000000', NULL, 1),
(6419668, 951977, 45004, '<td valign="top">Very creative use of focus and macro</td>', 'Very creative use of focus and macro', '2011-05-20 16:30:39.000000', NULL, 1),
(6419692, 951508, 58634, '<td valign="top">I really like how the shadows and lighted areas of this photograph are portrayed.</td>', 'I really like how the shadows and lighted areas of this photograph are portrayed.', '2011-05-20 16:59:26.000000', NULL, 1),
(6419693, 951593, 58634, '<td valign="top">I really like the softness in this image. And the purple in this flower is exquisite!</td>', 'I really like the softness in this image. And the purple in this flower is exquisite!', '2011-05-20 16:59:58.000000', NULL, 1),
(6419696, 952119, 58634, '<td valign="top">excellent focus.</td>', 'excellent focus.', '2011-05-20 17:00:27.000000', NULL, 1),
(6419698, 952047, 58634, '<td valign="top">The bokeh achieved here is marvelous. The flower stands out SO much! I love it!</td>', 'The bokeh achieved here is marvelous. The flower stands out SO much! I love it!', '2011-05-20 17:00:52.000000', NULL, 1),
(6419701, 951940, 58634, '<td valign="top">This is definitely a different perspective from most of the entries to this challenge. I like how colorful it is, but the background doesn''t work for me.. It''s too bright and it takes away the clarity that you could have. Also, I find the top corners with the blurred areas distracting.</td>', 'This is definitely a different perspective from most of the entries to this challenge. I like how colorful it is, but the background doesn''t work for me.. It''s too bright and it takes away the clarity that you could have. Also, I find the top corners with the blurred areas distracting.', '2011-05-20 17:02:18.000000', NULL, 1),
(6419706, 952098, 58634, '<td valign="top">Why the crop mid petal!? If it wasn''t for that, this would be an excellent image!</td>', 'Why the crop mid petal!? If it wasn''t for that, this would be an excellent image!', '2011-05-20 17:02:53.000000', NULL, 1),
(6419707, 951969, 58634, '<td valign="top">I just really like this image.</td>', 'I just really like this image.', '2011-05-20 17:03:15.000000', NULL, 1),
(6419708, 951240, 58634, '<td valign="top">Great use of depth of field. It makes this flower stand out amongst the other ''hearts'' in this challenge.</td>', 'Great use of depth of field. It makes this flower stand out amongst the other ''hearts'' in this challenge.', '2011-05-20 17:03:58.000000', NULL, 1),
(6419710, 952139, 58634, '<td valign="top">More color/contrast would''ve helped this picture majorly!</td>', 'More color/contrast would''ve helped this picture majorly!', '2011-05-20 17:04:59.000000', NULL, 1),
(6419717, 952173, 58634, '<td valign="top">What you have decided to focus in this image is lovely, however, I find that too much is out of focus for my liking.</td>', 'What you have decided to focus in this image is lovely, however, I find that too much is out of focus for my liking.', '2011-05-20 17:11:36.000000', NULL, 1),
(6419720, 951449, 58634, '<td valign="top">My favorite flower :D<br/> <br/>I like the composition, and the crop, too.</td>', 'My favorite flower :D I like the composition, and the crop, too.', '2011-05-20 17:12:11.000000', NULL, 1),
(6419721, 952172, 58634, '<td valign="top">Too many. I think you always have to have a point of focus, and something that contrasts the main thing.</td>', 'Too many. I think you always have to have a point of focus, and something that contrasts the main thing.', '2011-05-20 17:13:00.000000', NULL, 1),
