(6419729, 951390, 58634, '<td valign="top">I see what you tried to do there, but I just don''t think it worked out. The plant itself is too dark.</td>', 'I see what you tried to do there, but I just don''t think it worked out. The plant itself is too dark.', '2011-05-20 17:17:05.000000', NULL, 1),
(6419730, 951929, 58634, '<td valign="top">Nice composition, and I like that you tilted it.</td>', 'Nice composition, and I like that you tilted it.', '2011-05-20 17:17:35.000000', NULL, 1),
(6419731, 951848, 58634, '<td valign="top">Grainy and undefined.</td>', 'Grainy and undefined.', '2011-05-20 17:18:11.000000', NULL, 1),
