(6419734, 951959, 58634, '<td valign="top">Lovely use of lighting!</td>', 'Lovely use of lighting!', '2011-05-20 17:20:03.000000', NULL, 1),
(6419735, 952168, 58634, '<td valign="top">IMO, the colors in this image clash too much.</td>', 'IMO, the colors in this image clash too much.', '2011-05-20 17:20:28.000000', NULL, 1),
(6419738, 951972, 58634, '<td valign="top">Beautiful. Love the dark background and the definition that the petals have.</td>', 'Beautiful. Love the dark background and the definition that the petals have.', '2011-05-20 17:21:00.000000', NULL, 1),
