(6420568, 951308, 98339, '<td valign="top">I guess for me the composition of this just isn''t doing the trick for me...personally I''d rather see alot more "flower" and your BG in this makes this appear to be an indoor/studio shot...might not be...but it does do that</td>', 'I guess for me the composition of this just isn''t doing the trick for me...personally I''d rather see alot more "flower" and your BG in this makes this appear to be an indoor/studio shot...might not be...but it does do that', '2011-05-21 13:18:19.000000', NULL, 1),
(6420577, 952140, 124815, '<td valign="top">Quite a field here and a great approach for the challenge. Congratulation!<br/>As I look at it more and more, I must say that in my opinion it''s a lot more powerful if you cut the top and leave just a sea of stones.<br/>This being said, I give you a 9.</td>', 'Quite a field here and a great approach for the challenge. Congratulation!As I look at it more and more, I must say that in my opinion it''s a lot more powerful if you cut the top and leave just a sea of stones.This being said, I give you a 9.', '2011-05-21 13:25:04.000000', NULL, 1),
(6420582, 952009, 131377, '<td valign="top">This seems just a TOUCH fuzzy to me. It''s an incredible image with the different colored flowers, and the flowers are gorgeous, but it''s just a bit out of focus.</td>', 'This seems just a TOUCH fuzzy to me. It''s an incredible image with the different colored flowers, and the flowers are gorgeous, but it''s just a bit out of focus.', '2011-05-21 13:45:03.000000', NULL, 1),
(6420585, 951559, 131377, '<td valign="top">This is really cool. It''s a great photo. But for some reason.. I don''t know if it''s the editing or what.. It looks artificial to me. The different colors and terrain (and sky) clash so much that it almost looks pasted together. I love the bright colors and the fact that you were able to capture SO MANY different types of landscapes together all at once, but it''s not something I''d hang on my wall. It almost looks over-edited.</td>', 'This is really cool. It''s a great photo. But for some reason.. I don''t know if it''s the editing or what.. It looks artificial to me. The different colors and terrain (and sky) clash so much that it almost looks pasted together. I love the bright colors and the fact that you were able to capture SO MANY different types of landscapes together all at once, but it''s not something I''d hang on my wall. It almost looks over-edited.', '2011-05-21 13:49:07.000000', NULL, 1),
(6420586, 952115, 131377, '<td valign="top">My favorite flowers. :)</td>', 'My favorite flowers. :)', '2011-05-21 13:49:40.000000', NULL, 1),
(6420588, 951692, 131377, '<td valign="top">I''m not digging the reddish glow coming off some of the flowers, but it''s just an opinion I suppose. This is a really neat flower arrangement. It''d be awesome to visit in person.</td>', 'I''m not digging the reddish glow coming off some of the flowers, but it''s just an opinion I suppose. This is a really neat flower arrangement. It''d be awesome to visit in person.', '2011-05-21 13:51:00.000000', NULL, 1),
(6420590, 951723, 131377, '<td valign="top">LOL cute! :) 9</td>', 'LOL cute! :) 9', '2011-05-21 13:52:01.000000', NULL, 1),
(6420591, 952024, 131377, '<td valign="top">Seems a bit dark &amp; dull.. Almost like something you''d see on a funeral home ad. However, if your weather has been anything like ours, I can see why the picture came out a bit dark.</td>', 'Seems a bit dark & dull.. Almost like something you''d see on a funeral home ad. However, if your weather has been anything like ours, I can see why the picture came out a bit dark.', '2011-05-21 13:53:54.000000', NULL, 1),
(6420592, 951749, 131377, '<td valign="top">Gorgeous image! 9</td>', 'Gorgeous image! 9', '2011-05-21 13:54:13.000000', NULL, 1),
(6420593, 951064, 131377, '<td valign="top">What is it?</td>', 'What is it?', '2011-05-21 13:55:47.000000', NULL, 1),
(6420596, 951891, 131377, '<td valign="top">I think this barely meets the challenge.. Idk.. To me, it just isn''t very attractive, but then people who like street art might think it''s awesome. I really can''t rate it.</td>', 'I think this barely meets the challenge.. Idk.. To me, it just isn''t very attractive, but then people who like street art might think it''s awesome. I really can''t rate it.', '2011-05-21 14:09:37.000000', NULL, 1),
(6420597, 952111, 131377, '<td valign="top">Great idea.. Poor execution. It would look alot better if it were more in focus, I think. :)</td>', 'Great idea.. Poor execution. It would look alot better if it were more in focus, I think. :)', '2011-05-21 14:10:49.000000', NULL, 1),
(6420629, 951800, 58634, '<td valign="top">I really like how colorful this picture is. The thing that bothers me is that you''ve got straight lines colors, and they''re tilted making it awkward. Also, a lower angle or different composition to include some of the elements in the background more professionaly, like the John Deer, etc would''ve helped a lot.</td>', 'I really like how colorful this picture is. The thing that bothers me is that you''ve got straight lines colors, and they''re tilted making it awkward. Also, a lower angle or different composition to include some of the elements in the background more professionaly, like the John Deer, etc would''ve helped a lot.', '2011-05-21 14:59:10.000000', NULL, 1),
(6420633, 951290, 58634, '<td valign="top">For some reason, and suprisingly enough, I''m not crazy about the bokeh created in this image. I don''t know but the dark patch right at the center is distracting and I think it takes away from the flower.</td>', 'For some reason, and suprisingly enough, I''m not crazy about the bokeh created in this image. I don''t know but the dark patch right at the center is distracting and I think it takes away from the flower.', '2011-05-21 15:01:21.000000', NULL, 1),
(6420637, 951945, 58634, '<td valign="top">To me, this is an example of pointing and shooting and being done with it. In my opinion, you could''ve done better to attempt to get an interesting angle, or better lighting, or some depth of field. Also, it doesn''t seem like you attempted any sort of post processing to make your image pop.</td>', 'To me, this is an example of pointing and shooting and being done with it. In my opinion, you could''ve done better to attempt to get an interesting angle, or better lighting, or some depth of field. Also, it doesn''t seem like you attempted any sort of post processing to make your image pop.', '2011-05-21 15:03:56.000000', NULL, 1),
(6420641, 951268, 58634, '<td valign="top">It looos Christmas-y to me. I guess it''s the colors... For such a tight shot, I think you could''ve done better by having a sharper, better focused flower to really make it stand out. <br/>However, the bokeh ended up working nicely.</td>', 'It looos Christmas-y to me. I guess it''s the colors... For such a tight shot, I think you could''ve done better by having a sharper, better focused flower to really make it stand out. However, the bokeh ended up working nicely.', '2011-05-21 15:05:47.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6420642, 952089, 58634, '<td valign="top">The lovely bokeh colors are well, lovely. I really like it. <br/>Composition is excelent, and so is focus. The only slight detail that bothers me is the little thing hanging from the flower, but it''s small.</td>', 'The lovely bokeh colors are well, lovely. I really like it. Composition is excelent, and so is focus. The only slight detail that bothers me is the little thing hanging from the flower, but it''s small.', '2011-05-21 15:06:46.000000', NULL, 1),
(6420643, 951560, 58634, '<td valign="top">I think you could''ve made this image pop out a lot more! I''m curious to see how you achieved the black background in a natural setting, too.</td>', 'I think you could''ve made this image pop out a lot more! I''m curious to see how you achieved the black background in a natural setting, too.', '2011-05-21 15:07:33.000000', NULL, 1),
(6420644, 951882, 58634, '<td valign="top">IMO, the stem poking ''out'' from behind the flower is distracting and it leads the eyes elsewhere that''s not important in the picture. I like that the flower is coming from the corner, however, I think the composition isn''t the best.</td>', 'IMO, the stem poking ''out'' from behind the flower is distracting and it leads the eyes elsewhere that''s not important in the picture. I like that the flower is coming from the corner, however, I think the composition isn''t the best.', '2011-05-21 15:08:46.000000', NULL, 1),
(6420645, 951949, 58634, '<td valign="top">I very much so like the fgow in this plant. The lights and shadows stand out a lot.</td>', 'I very much so like the fgow in this plant. The lights and shadows stand out a lot.', '2011-05-21 15:09:19.000000', NULL, 1),
(6420646, 951575, 58634, '<td valign="top">Excellent macro! Clever title!</td>', 'Excellent macro! Clever title!', '2011-05-21 15:09:46.000000', NULL, 1),
