(6421572, 952127, 67258, '<td valign="top">Oh what a delightful flower - some type of magnolia?  Gorguous!</td>', 'Oh what a delightful flower - some type of magnolia?  Gorguous!', '2011-05-22 18:46:04.000000', NULL, 1),
(6421573, 951508, 67258, '<td valign="top">Excellent control of your exposure on a tricky subject - and also retained good textural detail.</td>', 'Excellent control of your exposure on a tricky subject - and also retained good textural detail.', '2011-05-22 18:46:05.000000', NULL, 1),
(6421574, 952056, 67258, '<td valign="top">The soft echo is lovely.</td>', 'The soft echo is lovely.', '2011-05-22 18:46:08.000000', NULL, 1),
(6421578, 951723, 104230, '<td valign="top">Ha.  Cute, and well captured, with great exposure for the white petals (just a bit of blowout on the upper left).  I love the patterns at the center of the right most flower.</td>', 'Ha.  Cute, and well captured, with great exposure for the white petals (just a bit of blowout on the upper left).  I love the patterns at the center of the right most flower.', '2011-05-22 18:55:17.000000', NULL, 1),
