(6423576, 951296, 64446, '<td valign="top">Love the sharp focus on the subject with a great bg. Wonderful colors palette.</td>', 'Love the sharp focus on the subject with a great bg. Wonderful colors palette.', '2011-05-24 18:12:06.000000', NULL, 1),
(6423577, 952022, 64446, '<td valign="top">I like the simplicity. Very nice warm colors too.</td>', 'I like the simplicity. Very nice warm colors too.', '2011-05-24 18:12:14.000000', NULL, 1),
(6423578, 952151, 12611, '<td valign="top">stunning; great powdery detail</td>', 'stunning; great powdery detail', '2011-05-24 18:15:18.000000', NULL, 1),
(6423579, 951275, 12611, '<td valign="top">a breath of fresh air in this challenge, literally and figuratively.</td>', 'a breath of fresh air in this challenge, literally and figuratively.', '2011-05-24 18:16:00.000000', NULL, 1),
(6423580, 952065, 12611, '<td valign="top">What makes this shot is the use of purple and green, that really creates depth and contrast. the composition is a bit lacking, but it works with the title.</td>', 'What makes this shot is the use of purple and green, that really creates depth and contrast. the composition is a bit lacking, but it works with the title.', '2011-05-24 18:18:16.000000', NULL, 1),
