(6423673, 952130, 114225, '<td valign="top">The colors palette of this photo is simply amazing.</td>', 'The colors palette of this photo is simply amazing.', '2011-05-24 21:18:30.000000', NULL, 1),
(6423689, 951275, 119419, '<td valign="top">Love the panorama feel about this, combined with the closeness of the Barley (I finally read the title ) pods and flowers. Such a great duality. The colours are so vivid and subtle, a lot of likable tension and contrast. Good work.<br/><br/><i>Message edited by author 2011-05-25 06:05:45.</i></td>', 'Love the panorama feel about this, combined with the closeness of the Barley (I finally read the title ) pods and flowers. Such a great duality. The colours are so vivid and subtle, a lot of likable tension and contrast. Good work.', '2011-05-24 21:50:50.000000', '2011-05-25 07:05:45.000000', 1),
(6423691, 952126, 119419, '<td valign="top">Love this, looks like a bridal bouquet.</td>', 'Love this, looks like a bridal bouquet.', '2011-05-24 21:51:26.000000', NULL, 1),
(6423692, 951936, 119419, '<td valign="top">Nice blur gives me a feeling of the meadow in dapple light. Lovely.</td>', 'Nice blur gives me a feeling of the meadow in dapple light. Lovely.', '2011-05-24 21:52:19.000000', NULL, 1),
(6423693, 952076, 119419, '<td valign="top">Took a little while but coming back I like it more and more, has a good vitality.</td>', 'Took a little while but coming back I like it more and more, has a good vitality.', '2011-05-24 21:53:13.000000', NULL, 1),
