(6424715, 951906, 45651, '<td valign="top">This was a pure and simple back-lit photo because the background was in deep shadows and I didn''t want to blow the highlights the background goes to black. Nothing tricky about it. <br/> <br/>Thanks for the great comments.</td>', 'This was a pure and simple back-lit photo because the background was in deep shadows and I didn''t want to blow the highlights the background goes to black. Nothing tricky about it.  Thanks for the great comments.', '2011-05-25 20:59:47.000000', NULL, 0),
(6424740, 951275, 130849, '<td valign="top">Congrats on blue!</td>', 'Congrats on blue!', '2011-05-25 21:52:45.000000', NULL, 0),
(6424741, 951840, 130849, '<td valign="top">Congrats on red!</td>', 'Congrats on red!', '2011-05-25 21:53:12.000000', NULL, 0),
(6424742, 951559, 130849, '<td valign="top">Congrats on yellow!</td>', 'Congrats on yellow!', '2011-05-25 21:53:45.000000', NULL, 0),
(6424744, 951885, 130849, '<td valign="top">Congrats on the HM!</td>', 'Congrats on the HM!', '2011-05-25 21:54:02.000000', NULL, 0),
(6424756, 951949, 129807, '<td valign="top">Well to my surprise it didn''t totally tank!<br/>I know it''s too soft but I didn''t have the chance to change lenses at that point.<br/>To be perfectly honest, I wasn''t really thinking about the background, I was too busy concentrating on getting the sunlight shining through; I''ll try to be more aware next time.<br/>Thanks everyone for the comments - I appreciate your opinions because it teaches me something nearly every time.</td>', 'Well to my surprise it didn''t totally tank!I know it''s too soft but I didn''t have the chance to change lenses at that point.To be perfectly honest, I wasn''t really thinking about the background, I was too busy concentrating on getting the sunlight shining through; I''ll try to be more aware next time.Thanks everyone for the comments - I appreciate your opinions because it teaches me something nearly every time.', '2011-05-25 22:15:07.000000', NULL, 0),
(6424757, 951559, 79155, '<td valign="top">Great shot give me encouragement to keep taking pics.</td>', 'Great shot give me encouragement to keep taking pics.', '2011-05-25 22:15:13.000000', NULL, 0),
(6424761, 951275, 30982, '<td valign="top">Reminded me of Germany.  Not all that far away!  Lovely.</td>', 'Reminded me of Germany.  Not all that far away!  Lovely.', '2011-05-25 22:32:09.000000', NULL, 0),
(6424803, 952089, 130849, '<td valign="top">Congrats on top 10!  Beautiful tones and DOF.</td>', 'Congrats on top 10!  Beautiful tones and DOF.', '2011-05-25 23:03:33.000000', NULL, 0),
(6424806, 951733, 130849, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Revecca:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by BrennanOB:</b></div><hr/><i> I am surprised by the low placing of this image. While it doesn''t show much sense of place it makes up for it in delivering a great sense of delicacy and texture, I had it in my top three. </i></td></tr></table> <br/> <br/>I agree! </i></td></tr></table> <br/> <br/>I also agree!</td>', 'Originally posted by Revecca: Originally posted by BrennanOB: I am surprised by the low placing of this image. While it doesn''t show much sense of place it makes up for it in delivering a great sense of delicacy and texture, I had it in my top three.   I agree!   I also agree!', '2011-05-25 23:10:23.000000', NULL, 0),
(6424808, 952096, 130849, '<td valign="top">Love this!  Congrats on top 15.</td>', 'Love this!  Congrats on top 15.', '2011-05-25 23:11:33.000000', NULL, 0),
(6424814, 951296, 130849, '<td valign="top">Nice one, Karen!  I like the color, comp and bokeh.</td>', 'Nice one, Karen!  I like the color, comp and bokeh.', '2011-05-25 23:16:57.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6425033, 952095, 20577, '<td valign="top">Great shot Brian. You''ve got these macro shots down.<br/> <br/>My guess is you''ll never use a border again....</td>', 'Great shot Brian. You''ve got these macro shots down. My guess is you''ll never use a border again....', '2011-05-26 06:48:20.000000', NULL, 0),
(6425046, 951275, 108069, '<td valign="top">I dislike this photo immensely because it''s just a glaring reminder of what I wanted to do but I just did not have the time. I wouldn''t have done it as well. In fact, it would have paled in comparison. I may have even injured myself. But damn it this is how it looked in my mind. As Melethia mentioned below, our topography is very similar here (our two towns even look similar; though yours seems to have quite a bit more charm - also you''re much better at capturing and representing that charm). You continue to set the bar high for me, working with similar materials. Hearty congratulations.</td>', 'I dislike this photo immensely because it''s just a glaring reminder of what I wanted to do but I just did not have the time. I wouldn''t have done it as well. In fact, it would have paled in comparison. I may have even injured myself. But damn it this is how it looked in my mind. As Melethia mentioned below, our topography is very similar here (our two towns even look similar; though yours seems to have quite a bit more charm - also you''re much better at capturing and representing that charm). You continue to set the bar high for me, working with similar materials. Hearty congratulations.', '2011-05-26 07:25:56.000000', NULL, 0),
(6425165, 951064, 54645, '<td valign="top">A not so in your face version of "stop and smell the roses". Well done.</td>', 'A not so in your face version of "stop and smell the roses". Well done.', '2011-05-26 12:39:01.000000', NULL, 0),
(6425181, 951885, 39057, '<td valign="top">This is about to ribbon....</td>', 'This is about to ribbon....', '2011-05-26 13:16:25.000000', NULL, 0),
(6425184, 951275, 123348, '<td valign="top">Congratulations on the blue and this beautiful image! :)</td>', 'Congratulations on the blue and this beautiful image! :)', '2011-05-26 13:24:43.000000', NULL, 0),
(6425185, 951559, 123348, '<td valign="top">Breathtaking image, this was one of my favorites! Congratulations!</td>', 'Breathtaking image, this was one of my favorites! Congratulations!', '2011-05-26 13:26:11.000000', NULL, 0),
(6425300, 951275, 72579, '<td valign="top">Congrats! Beautiful picture! You have an amazing talent!</td>', 'Congrats! Beautiful picture! You have an amazing talent!', '2011-05-26 18:43:20.000000', NULL, 0),
