(6426405, 951559, 98022, '<td valign="top">Awesome image! Congrats on the yellow ribbon to match your yellow flowers!</td>', 'Awesome image! Congrats on the yellow ribbon to match your yellow flowers!', '2011-05-27 22:08:48.000000', NULL, 0),
(6426407, 951885, 98022, '<td valign="top">Outstanding image Doc! You are right about all of the contrasting colors, and the focus and lighting is spot-on. One of my favs. Congrats on the HM!</td>', 'Outstanding image Doc! You are right about all of the contrasting colors, and the focus and lighting is spot-on. One of my favs. Congrats on the HM!', '2011-05-27 22:11:33.000000', NULL, 0),
